const scans = $('Get completed scans').all().map(i => i.json);
const sheetRaw = $('Extract Sentrixs').first().json.sheet;
const sheet = JSON.parse(sheetRaw);
const careSiteMapping = $('Get care_site_mapping').all().map(i => i.json);

const scanMap = {};
scans.forEach(scan => {
  scanMap[scan.sentrix_id] = scan;
});

const careSiteMap = {};
careSiteMapping.forEach(row => {
  careSiteMap[row.care_site_source_value] = row.care_site_ref;
});

const results = [];
sheet.forEach(row => {
  const scan = scanMap[row.Barkod];
  if (scan) {
    results.push({
      json: {
        scan_ref: scan.uniqueref,
        sentrix_id: scan.sentrix_id,
        chiptype_ref: scan.chiptype_ref,
        performing_caresite_ref: scan.care_site_ref,
        position: row.Pozisyon,
        sample_id: row['Örnek'],
        requesting_caresite_ref: careSiteMap[row.Kurum] || null
      }
    });
  }
});

return results.length > 0 ? results : [{ json: { action: 'none' } }];

const data1 = JSON.parse($('Execute Command').first().json.stdout);
const data2 = JSON.parse($('Execute Command1').first().json.stdout);

const [headers, ...rows1] = data1.values;
const rows2 = data2.values || [];

const allRows = [...rows1, ...rows2];

return allRows.map(row => ({
  json: Object.fromEntries(headers.map((h, i) => [h, row[i] ?? '']))
}));

const items = $input.all();
const prevItems = $('Merge SQL and Sheet').all();
const results = [];

items.forEach((item, index) => {
  try {
    const parsed = JSON.parse(item.json.stdout);
    const prev = prevItems[index].json;
    results.push({
      json: {
        scan_ref: prev.scan_ref,
        sentrix_id: prev.sentrix_id,
        chiptype_ref: prev.chiptype_ref,
        performing_caresite_ref: prev.performing_caresite_ref,
        requesting_caresite_ref: prev.requesting_caresite_ref,
        position: prev.position,
        sample_id: prev.sample_id,
        green_idat_path: parsed.green_idat_path,
        red_idat_path: parsed.red_idat_path,
        total_rescan_count: parsed.total_rescan_count,
        position_rescan_count: parsed.position_rescan_count,
        is_rescanned: parsed.is_rescanned
      }
    });
  } catch {
    // parse hatası, atla
  }
});

return results;

