const checkResults = $('Check idat exists').all().map(i => i.json);
const parseResults = $('Parse').all().map(i => i.json); // SSH parse node adın ne?

const results = [];

parseResults.forEach((current, index) => {
  const dbRecord = checkResults[index] || {};

  if (!dbRecord.uniqueref) {
    results.push({ json: { ...current, action: 'insert' } });
  } else if (parseInt(dbRecord.rescan_count) !== current.position_rescan_count) {
    results.push({ json: { ...current, action: 'update', idat_ref: dbRecord.uniqueref } });
  } else {
    results.push({ json: { ...current, action: 'none' } });
  }
});

return results;

